import sys, json, random, collections, re; sys.path.insert(0,'.')
import bridge as B, pipeline as PL
вх0 = json.load(open('вх.json')); вх0['сід'] = 4242
СЦ = {
 'спека·парк·щоденне':   dict(нагода='щоденне', місце='парк', година=15, темп_c=31, паспорт=dict(подія='прогулянка парком і кава', формат='просто неба', ошатність=[2,4], година=15, темп_c=31, рух='багато ходити')),
 'холод·ресторан·вечір': dict(нагода='побачення', місце='ресторан', година=20, темп_c=5, опади='дощ', вітер=8, паспорт=dict(подія='вечеря в ресторані, дощ', формат='приміщення', ошатність=[6,8], година=20, темп_c=5, опади='так', рух='сидіти')),
 'офіс·18°C':            dict(нагода='робота', місце='офіс', година=9, темп_c=18, дрес_код='business_formal', паспорт=dict(подія='робочий день, зустріч із клієнтом', формат='приміщення', ошатність=[6,8], година=9, темп_c=18, дрес_код='business formal')),
 'весілля·гість·24°C':   dict(нагода='весілля_гість', місце='весілля_вечірнє', година=17, темп_c=24, паспорт=dict(подія='весілля подруги, гість', формат='змішано', ошатність=[7,9], година=17, темп_c=24, рух='ходити', тривалість_год=7)),
}
kb_теми = {}
import glob, io
for f in sorted(glob.glob('тема-*.md')):
    т = 'тема-' + re.match(r'тема-(\d+)', f).group(1); s = io.open(f, encoding='utf-8', errors='replace').read()
    for i in set(re.findall(r'\b(K-[A-Z]{2,5}-\d{2,3}(?:-[A-Z])?)\b', s)): kb_теми.setdefault(i, т)
for назва, сц in СЦ.items():
    п = PL.паспорт_з_json(json.dumps(dict(сц['паспорт']), ensure_ascii=False), {k: v for k, v in сц.items() if k != 'паспорт'}, сц['паспорт']['подія'])
    сцен_вх = {k: v for k, v in сц.items() if k != 'паспорт'}
    d = dict(вх0, сценарій=сцен_вх, паспорт=п, випадок='%s, %s, %02d:00, %s °C' % (сц['нагода'], сц['місце'], сц['година'], сц['темп_c']))
    r = json.loads(B.виклик('запити', json.dumps(d, ensure_ascii=False)))
    if r.get('помилка'): print(назва, 'ПОМИЛКА', r['помилка']); continue
    к = r['кандидати']; слоти = {s: len(v) for s, v in к.items()}
    взут = collections.Counter(next((t for t in ('чобот','черевик','угг','ботил','босоніж','сандал','мюлі','шльопан','кросів','кед','лофер','балетк','туфл','човник') if t in x['назва'].lower()), 'інше') for x in к.get('взуття', []))
    print('\n=== %s | пул %d | верхній_шар у пулі: %s | взуття: %s' % (назва, r['пул_речей'], слоти.get('верхній_шар', 'НЕМА'), dict(взут.most_common(6))))
    print('   ноти слотів:', {k: str(v)[:50] for k, v in (r.get('ноти_слотів') or {}).items() if v})
    print('   відсічено:', r['відсічено']['лічба'] if r.get('відсічено') else '—', '| ВИПАДОК руки 1:', re.search(r'ВИПАДОК[^\n]*\n?[^\n]*', r['руки']['1']).group(0).replace('\n',' ')[:110])
    d2 = B._застосувати_паспорт(d); F,T,_,_ = B._збірка(d2); пк = B._пакет(F,T,168,{},B._якір(d2),'conventional',B._самозвіт(d2),None)
    пак = B._пакет_каталогу(d2, F, T, пк, None)
    сцен = {k: d2['сценарій'][k] for k in B._ПОЛЯ_СЦЕНАРІЮ if d2['сценарій'].get(k) not in (None,'')}
    rnd = random.Random(11); акт = collections.Counter(); блок = collections.Counter(); теми = collections.Counter()
    for i in range(60):
        речі = (rnd.sample(к['сукня'],1) if (rnd.random()<0.35 and к.get('сукня')) else rnd.sample(к['верх'],1)+rnd.sample(к['низ'],1)) + rnd.sample(к['взуття'],1) + rnd.sample(к['сумка'],1)
        if к.get('верхній_шар') and rnd.random() < 0.7: речі += rnd.sample(к['верхній_шар'],1)
        в = PL.перевірити_від_моделі([x['id'] for x in речі], F, пак['_каталог'], T, dict(сцен), кандидати=пак['кандидати'], спец_слоти=пак.get('_спец_слоти'))
        for з in (в.get('знахідки') or []):
            if B._питання_або_нуль(з): continue
            акт[з['правило']] += 1; теми[kb_теми.get(з['правило'], '?')] += 1
        for б in (в.get('блокує') or []): блок[str(б)[:45]] += 1
    print('   живі правила (60 образів):', ', '.join('%s %d' % kv for kv in акт.most_common(12)))
    print('   по темах:', dict(теми), '| блокери:', dict(блок.most_common(4)))
    print('   бриф руки 1: рядків із ID', sum(1 for p in r['правила_рук']['B'] if p.get('правило')), '| теми брифа:', dict(collections.Counter(kb_теми.get(p.get('правило'),'?') for p in r['правила_рук']['B'] if p.get('правило'))))
